import{z as A,x as B,o as r,c as p,q as e,j as t,D as n,d as l,s,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"保形预测进 LLM","description":"","frontmatter":{"title":"保形预测进 LLM","date":"2026-09-27T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/conformal-prediction-llm.md","filePath":"llm/conformal-prediction-llm.md","lastUpdated":1791063341000}'),m={name:"llm/conformal-prediction-llm.md"};function d(c,a,g,f,D,h){const o=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=e('<h1 id="保形预测进-llm" tabindex="-1">保形预测进 LLM <a class="header-anchor" href="#保形预测进-llm" aria-label="Permalink to &quot;保形预测进 LLM&quot;">​</a></h1><div class="epigraph"><p>「模型说它对」不算数，要「错误率不超过 10%」才有合同价值——保形预测把 LLM 输出从意见变成带保证的集合。</p><footer>—— 据 Vovk 保形预测框架 (2005)；Angelopoulos–Bates《Conformal ML 入门》(2023)；Kumar et al. LLM 校准应用 (2023)</footer></div><p><a href="/llm/semantic-uncertainty">语义熵</a>给「这次在不在猜」的即时信号，本课给更硬的东西：<strong>统计保证</strong>。缺口是<strong>保形预测进 LLM</strong>——用校准集把任意不确定性分数转成「错误率 ≤ α 的预测集合」，分布无关、无需重训。它回答的是审计者的问题而非用户的问题。本课不进保形框架的渐近理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LLM 应用上生产线的障碍是「没法承诺错误率」：客服说「错误率 10%」，法务问「白纸黑字吗」。传统校准（Platt/温度缩放）给的是平均校准，不保证单条输出的错误率。缺口：<strong>有限样本、分布无关的单例保证</strong>——这正是 split conformal 的定义域。</p><p><span class="marginnote">术语翻译：保形预测（conformal prediction）= 给出预测<strong>集合</strong>而非点估计，保证以 ≥1−α 的概率覆盖真值；split conformal = 留一部分数据当校准集，算分数的分位数做阈值；覆盖（coverage）= 真值落在集合内的比例。</span></p><p><span class="marginnote">数字实例：抽取式问答，校准集 500 条，分数 = 1 −（含真答案的最短 span 的模型置信度）。取分数 90% 分位当阈值 λ=0.78：输出「答案 span 集合」，保证错误率 ≤ 10%。集合平均含 1.4 个候选——「多数时候一个、偶尔两个答案」，这就是可写进合同的承诺。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Split conformal 三步（以 QA 的 span 集合为例）：<strong>校准</strong>——留出集 n 条，每条算非一致性分数 \\(s_i\\)（1−正确 span 的模型分）；<strong>定阈</strong>——取 \\(\\hat q\\) = \\(\\lceil(n+1)(1-\\alpha)\\rceil/n\\) 分位；<strong>部署</strong>——新样本输出所有分数 \\(\\le\\hat q\\) 的候选（多个 span、多个答案选项）。LLM 场景的分数设计是全部学问：候选集来自采样（RAG 下多个 chunk）或 top-k；分数用语义熵、自洽度、verifier 打分皆可——保形框架对分数只要求「可交换性」，不要求它准。</p>',9)),(r(),t(i,null,{default:n(()=>[s(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%95%99%E5%87%BA%E6%A0%A1%E5%87%86%E9%9B%86%20n%20%E6%9D%A1%22%5D%20--%3E%20B%5B%22%E9%80%90%E6%9D%A1%E7%AE%97%E9%9D%9E%E4%B8%80%E8%87%B4%E5%88%86%E6%95%B0%20s_i%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%8F%96%20(1-%CE%B1)%20%E5%88%86%E4%BD%8D%20%E2%86%92%20%E9%98%88%E5%80%BC%20q%5E%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%96%B0%E6%A0%B7%E6%9C%AC%3A%20%E6%89%80%E6%9C%89%20s%20%E2%89%A4%20q%5E%20%E7%9A%84%E5%80%99%E9%80%89%E6%88%90%E9%9B%86%E5%90%88%22%5D%0A%20%20D%20--%3E%20E%7B%22%E9%9B%86%E5%90%88%E5%A4%A7%E5%B0%8F%3F%22%7D%0A%20%20E%20--%3E%7C%221%20%E4%B8%AA%22%7C%20F%5B%22%E9%AB%98%E7%BD%AE%E4%BF%A1%E5%8D%95%E7%AD%94%22%5D%0A%20%20E%20--%3E%7C%22%E5%A4%9A%2F%E7%A9%BA%22%7C%20G%5B%22%E8%A7%A6%E5%8F%91%E6%A3%80%E7%B4%A2%2F%E6%8B%92%E7%AD%94%2F%E4%BA%BA%E5%B7%A5%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：像质检抽检定允差——不知道每件产品（每条输出）的个体质量，但抽 500 件量出「误差分布的 90% 分位是 0.78」，往后每件的承诺按这条线开。承诺的不是「这件一定好」，是「十件里至多一件超差」——这恰是审计语言。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[l("保证成立的机制只有一条："),E("strong",null,"可交换性"),l("（校准数据与部署数据同分布、可交换）。数学核心：校准分数与测试分数在秩上对称，\\(\\Pr(s_{test}\\le\\hat q)\\ge1-\\alpha\\) 严格成立——不依赖分布形状、不依赖分数准不准。LLM 场景的机制重心因此落在「分数怎么设计才让集合小而有用」：分数越好（区分对错越强），同样 α 下集合越小；分数烂则集合巨大——保证依然成立，只是没用。生产模式的闭环：集合大小本身作为路由信号——单候选直出、多候选让 verifier 精排、空集或大集转人工/检索。")],-1)),(r(),t(i,null,{default:n(()=>[s(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%BF%9D%E8%AF%81%E4%B8%BA%E4%BD%95%E7%A1%AC%3F%22%7D%20--%3E%20R%5B%22%E5%8F%AF%E4%BA%A4%E6%8D%A2%E6%80%A7%20%E2%86%92%20%E7%A7%A9%E5%AF%B9%E7%A7%B0%22%5D%0A%20%20R%20--%3E%20S%5B%22%E8%A6%86%E7%9B%96%20%E2%89%A51-%CE%B1%20%E4%B8%A5%E6%A0%BC%E6%88%90%E7%AB%8B%22%5D%0A%20%20T%7B%22%E9%9B%86%E5%90%88%E4%B8%BA%E4%BB%80%E4%B9%88%E5%A4%A7%3F%22%7D%20--%3E%20U%5B%22%E5%88%86%E6%95%B0%E5%8C%BA%E5%88%86%E5%BA%A6%E5%B7%AE%22%5D%0A%20%20U%20--%3E%20V%5B%22%E4%BF%9D%E8%AF%81%E8%BF%98%E5%9C%A8%2C%20%E5%AE%9E%E7%94%A8%E6%80%A7%E6%B2%A1%E4%BA%86%22%5D%0A%20%20S%20--%3E%20W%5B%22%E9%97%AD%E7%8E%AF%3A%20%E9%9B%86%E5%90%88%E5%A4%A7%E5%B0%8F%E5%BD%93%E8%B7%AF%E7%94%B1%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20V%20--%3E%20W%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=e('<p><span class="marginnote">常见误区：把保形集合的「错误率 ≤ α」读成「答案正确」——它承诺的是集合包含真值，集合里有垃圾候选照样保真；另一误区是校准集用了一次后不更新——分布漂移（新话题、新用户群）击穿可交换性，保证静默失效，线上要监控实际覆盖。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>保证的前提是<strong>可交换</strong>，流式/自强化场景（用户反馈改变分布）需自适应保形（online conformal），覆盖保证从严格变渐进。集合形式的定义是自由度也是坑：「答案集合」对开放生成（摘要）无法枚举，实践多退化为「声明级抽取 + 保形」或「拒答决策的二元保形」。分数工程的成本：好分数（语义熵、verifier）让集合实用，但 verifier 本身的错误率不被保证覆盖。与语义熵的分工重申：语义熵是<strong>分数</strong>，保形是<strong>把分数变成合同的框架</strong>——先有好温度计，才有可信的天气预报。与幻觉审计的关系：CQA 系统「每 100 条至多 10 条错」的承诺，最终靠这套机制落到纸面。</p><p><span class="marginnote">直觉类比：语义熵是体温计，保形是「按体温计读数定发烧线」的质检流程——体温计准不准（分数质量）决定流程好用不好用，但「90% 分位这条线」的有效性只依赖「抽检与出货同源」（可交换性），不依赖体温计牌子的对错。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>保形 = 非一致分数 + 校准集分位 → 覆盖 ≥1−α 的预测集合。</li><li>对分数不挑食：分数越好集合越小，保证恒成立。</li><li>可交换性是命门；分布漂移需 online 保形 + 覆盖监控。</li><li>出处：Vovk et al.《Algorithmic Learning in a Random World》2005；Angelopoulos–Bates 2023；Kumar et al. 2023。</li></ul>',6))])}const C=A(m,[["render",d]]);export{_ as __pageData,C as default};
